-- Knowledge Base library: a platform-wide set of articles that every agency can
-- read, plus each agency's own on/off choice per article.
--
--   kb_library_articles   one row per shared article (no org, no client data).
--                         kind = mediflow_guide (how Mediflow works) or
--                         medicare_reference (general Medicare notes).
--                         default_enabled is what an agency gets until it
--                         chooses; needs_review marks notes whose figures or
--                         rules may be out of date (they start switched off).
--   kb_library_choices    an agency's explicit choice for one library article.
--                         No row = use default_enabled.
--
-- Active library articles that match a question are handed to the AI assistant
-- the same way agency-written kb_articles are. Never store client data here.
CREATE TABLE IF NOT EXISTS "kb_library_articles" (
	"id" text PRIMARY KEY NOT NULL,
	"key" text NOT NULL,
	"category" text NOT NULL,
	"title" text NOT NULL,
	"content" text NOT NULL,
	"keywords" text[] DEFAULT '{}'::text[] NOT NULL,
	"kind" text NOT NULL,
	"default_enabled" boolean DEFAULT true NOT NULL,
	"needs_review" boolean DEFAULT false NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "kb_library_articles_key_idx" ON "kb_library_articles" USING btree ("key");
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "kb_library_choices" (
	"org_id" text NOT NULL,
	"article_id" text NOT NULL,
	"enabled" boolean NOT NULL,
	"updated_by" text,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "kb_library_choices_pk" PRIMARY KEY ("org_id","article_id")
);
--> statement-breakpoint
-- Foreign keys in guarded statements: CREATE TABLE IF NOT EXISTS skips its
-- whole body (inline constraints included) when the table already exists.
DO $$ BEGIN
  ALTER TABLE "kb_library_choices" ADD CONSTRAINT "kb_library_choices_org_id_organizations_id_fk"
    FOREIGN KEY ("org_id") REFERENCES "public"."organizations"("id") ON DELETE cascade ON UPDATE no action;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;
--> statement-breakpoint
DO $$ BEGIN
  ALTER TABLE "kb_library_choices" ADD CONSTRAINT "kb_library_choices_article_id_kb_library_articles_id_fk"
    FOREIGN KEY ("article_id") REFERENCES "public"."kb_library_articles"("id") ON DELETE cascade ON UPDATE no action;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;
--> statement-breakpoint
DO $$ BEGIN
  ALTER TABLE "kb_library_choices" ADD CONSTRAINT "kb_library_choices_updated_by_users_id_fk"
    FOREIGN KEY ("updated_by") REFERENCES "public"."users"("id") ON DELETE set null ON UPDATE no action;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;
--> statement-breakpoint
-- Starting content: 31 Mediflow guides (on by default) and 61 general
-- Medicare notes carried over from agencyBRIDGE (off by default: a 2025
-- snapshot whose figures and rules need review before an agency relies on them).
-- Re-running never overwrites an existing row.
INSERT INTO "kb_library_articles"
  ("id", "key", "category", "title", "content", "keywords", "kind", "default_enabled", "needs_review")
